{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio for the district (lower values mean fewer students per teacher). Calculated as Enrollment / NumTeachers.",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "Academic performance measured as the average of the district's 5th-grade standardized reading and math scores.",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Total enrollment in the district (used as a size control; also log-transformed in the model).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Enrollment",
          "LogEnrollment"
        ]
      },
      {
        "description": "Number of teachers (full-time equivalents) in the district. Used to compute the student-teacher ratio and checked for data validity.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "NumTeachers"
        ]
      },
      {
        "description": "Expenditure per student (district-level), controls for resource level.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ExpenditurePerStudent"
        ]
      },
      {
        "description": "District average income (in thousands USD), controls for socioeconomic status.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "IncomeK"
        ]
      },
      {
        "description": "Percent qualifying for CalWorks (income assistance) — socioeconomic control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PercCalWorks"
        ]
      },
      {
        "description": "Percent qualifying for reduced-price lunch — socioeconomic control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PercReducedLunch"
        ]
      },
      {
        "description": "Percent of English learners in the district — controls for language composition.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PercEngLearners"
        ]
      },
      {
        "description": "Computers per student (NumComputers / Enrollment) — proxy for technology availability.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ComputersPerStudent",
          "NumComputers"
        ]
      },
      {
        "description": "County (categorical) to account for regional fixed effects and policy/context differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "County"
        ]
      },
      {
        "description": "Grade span of the district (categorical; KK-06 or KK-08) to control structural differences across district types.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "GradeSpan"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Coerce numeric columns (use dataset field names from schema)\n    df['Enrollment'] = pd.to_numeric(df['feature6'], errors='coerce')\n    df['NumTeachers'] = pd.to_numeric(df['feature7'], errors='coerce')\n    df['PercCalWorks'] = pd.to_numeric(df['feature8'], errors='coerce')\n    df['PercReducedLunch'] = pd.to_numeric(df['feature9'], errors='coerce')\n    df['NumComputers'] = pd.to_numeric(df['feature10'], errors='coerce')\n    df['ExpenditurePerStudent'] = pd.to_numeric(df['feature11'], errors='coerce')\n    df['IncomeK'] = pd.to_numeric(df['feature12'], errors='coerce')\n    df['PercEngLearners'] = pd.to_numeric(df['feature13'], errors='coerce')\n    df['ReadingScore'] = pd.to_numeric(df['feature14'], errors='coerce')\n    df['MathScore'] = pd.to_numeric(df['feature15'], errors='coerce')\n\n    # Categorical variables\n    df['County'] = df['feature4'].astype('category')\n    df['GradeSpan'] = df['feature5'].astype('category')\n\n    # Remove rows with invalid or zero denominators\n    df = df[(df['Enrollment'] > 0) & (df['NumTeachers'] > 0)]\n\n    # Drop rows missing key outcome or denominator values\n    df = df.dropna(subset=['ReadingScore', 'MathScore', 'Enrollment', 'NumTeachers'])\n\n    # Compute primary variables\n    df['StudentTeacherRatio'] = df['Enrollment'] / df['NumTeachers']\n    df['AvgScore'] = df[['ReadingScore', 'MathScore']].mean(axis=1)\n    df['ComputersPerStudent'] = df['NumComputers'] / df['Enrollment']\n    df['LogEnrollment'] = np.log1p(df['Enrollment'])\n\n    # Trim extreme StudentTeacherRatio outliers (optional conservative filter)\n    # Keep observations within 4 SDs of the mean ratio to avoid single extreme districts dominating results\n    ratio_mean = df['StudentTeacherRatio'].mean()\n    ratio_std = df['StudentTeacherRatio'].std()\n    if pd.notnull(ratio_mean) and pd.notnull(ratio_std) and ratio_std > 0:\n        df = df[(df['StudentTeacherRatio'] - ratio_mean).abs() <= 4 * ratio_std]\n\n    # Impute remaining missing control values with median (conservative simple approach)\n    for col in ['PercCalWorks', 'PercReducedLunch', 'ExpenditurePerStudent', 'IncomeK', 'PercEngLearners', 'ComputersPerStudent']:\n        if col in df.columns:\n            median_val = df[col].median()\n            df[col] = df[col].fillna(median_val)\n\n    # Final check: drop any rows missing the modeling columns\n    model_cols = ['AvgScore', 'StudentTeacherRatio', 'ExpenditurePerStudent', 'IncomeK', 'PercCalWorks', 'PercReducedLunch', 'PercEngLearners', 'ComputersPerStudent', 'LogEnrollment', 'County', 'GradeSpan']\n    df = df.dropna(subset=[c for c in model_cols if c in df.columns])\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    import statsmodels.formula.api as smf\n\n    # Model specification:\n    # AvgScore is regressed on StudentTeacherRatio (primary IV) and a set of controls.\n    # County and GradeSpan are included as categorical fixed effects.\n    formula = (\n        'AvgScore ~ StudentTeacherRatio + ExpenditurePerStudent + IncomeK + '\n        'PercCalWorks + PercReducedLunch + PercEngLearners + ComputersPerStudent + LogEnrollment + '\n        'C(County) + C(GradeSpan)'\n    )\n\n    # Fit OLS with robust (HC3) standard errors to reduce influence of heteroskedasticity\n    model = smf.ols(formula, data=df).fit(cov_type='HC3')\n\n    # Return the fitted model object (caller can inspect summary(), params, conf_int(), etc.)\n    return model\n"
}
